	m_coinctrl = data;
	LOGMCU("qixmcu_state, coinctrl_w = %02X\n", data);

data &= mem_mask;
	machine().bookkeeping().coin_lockout_w(0, BIT(~data, 6));
	machine().bookkeeping().coin_counter_w(0, BIT(data, 7));

// write to the sound chip
	if (!state && m_sn76489_ctrl[Which])
		m_sn[Which]->write(m_pia[Which + 1]->b_output());

	m_sn76489_ctrl[Which] = bool(state);

// write to the sound chip
	if (!state && m_sn76489_ctrl[Which])
		m_sn[Which]->write(m_pia[Which + 1]->b_output());

	m_sn76489_ctrl[Which] = bool(state);

/* on the rising edge, latch the scanline */
	if (state)
	{
		uint16_t const ma = m_crtc->get_ma();
		uint8_t const ra = m_crtc->get_ra();

		/* RA0-RA2 goes to D0-D2 and MA5-MA9 goes to D3-D7 */
		*m_scanline_latch = ((ma >> 2) & 0xf8) | (ra & 0x07);
	}

